-- =====================================================================\n-- V16: Identity por obra, plantillas documentales, puente integración\n-- =====================================================================\n\nCREATE TYPE project_role AS ENUM (\n  'OWNER',\n  'PROJECT_ENGINEER',\n  'SAFETY_LEAD',\n  'FINANCE',\n  'COMPLIANCE_LEAD',\n  'SUBCONTRACTOR_ADMIN',\n  'VIEWER'\n);\n\nCREATE TABLE app_user (\n  tenant_id   uuid NOT NULL,\n  user_id     uuid NOT NULL,\n  email       varchar(200) NOT NULL,\n  display_name varchar(200) NOT NULL,\n  password_hash varchar(200), -- bcrypt; null = solo SSO/API key\n  active      boolean NOT NULL DEFAULT true,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, user_id),\n  UNIQUE (tenant_id, email)\n);\nALTER TABLE app_user ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_app_user ON app_user\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\nCREATE TABLE project_membership (\n  tenant_id   uuid NOT NULL,\n  project_id  uuid NOT NULL,\n  user_id     uuid NOT NULL,\n  role        project_role NOT NULL,\n  active      boolean NOT NULL DEFAULT true,\n  granted_at  timestamptz NOT NULL DEFAULT now(),\n  granted_by  uuid,\n  PRIMARY KEY (tenant_id, project_id, user_id, role)\n);\nALTER TABLE project_membership ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_project_membership ON project_membership\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\nCREATE INDEX idx_membership_user ON project_membership (tenant_id, user_id)\n  WHERE active = true;\n\n-- API keys operativas (servicio a servicio / front)\nCREATE TABLE api_credential (\n  tenant_id     uuid NOT NULL,\n  credential_id uuid NOT NULL,\n  user_id       uuid NOT NULL,\n  api_key_hash  varchar(128) NOT NULL,\n  label         varchar(120) NOT NULL,\n  active        boolean NOT NULL DEFAULT true,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  last_used_at  timestamptz,\n  PRIMARY KEY (tenant_id, credential_id)\n);\nALTER TABLE api_credential ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_api_credential ON api_credential\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\n-- Plantillas documentales (contratos, RFIs, cartas)\nCREATE TABLE document_template (\n  tenant_id     uuid NOT NULL,\n  template_id   uuid NOT NULL,\n  code          varchar(80) NOT NULL,\n  name          varchar(200) NOT NULL,\n  category      varchar(40) NOT NULL, -- CONTRACT, RFI, CO, LETTER, OSHA\n  body_markdown text NOT NULL,\n  variables_json jsonb NOT NULL DEFAULT '[]',\n  version       int NOT NULL DEFAULT 1,\n  active        boolean NOT NULL DEFAULT true,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, template_id),\n  UNIQUE (tenant_id, code, version)\n);\nALTER TABLE document_template ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_document_template ON document_template\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\nCREATE TABLE assembled_document (\n  tenant_id     uuid NOT NULL,\n  assembly_id   uuid NOT NULL,\n  template_id   uuid NOT NULL,\n  project_id    uuid,\n  output_markdown text NOT NULL,\n  variables_used  jsonb NOT NULL,\n  assembled_by  uuid NOT NULL,\n  assembled_at  timestamptz NOT NULL DEFAULT now(),\n  document_id   uuid, -- si se materializó a storage\n  PRIMARY KEY (tenant_id, assembly_id)\n);\nALTER TABLE assembled_document ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_assembled_document ON assembled_document\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\n-- Puente integración (Procore / ERP) — outbox de sincronización\nCREATE TYPE integration_system AS ENUM ('PROCORE', 'ERP_SAP', 'ERP_ORACLE', 'GENERIC_WEBHOOK');\nCREATE TYPE integration_direction AS ENUM ('INBOUND', 'OUTBOUND');\nCREATE TYPE integration_status AS ENUM ('PENDING', 'PROCESSING', 'SUCCEEDED', 'FAILED', 'DEAD');\n\nCREATE TABLE integration_outbox (\n  tenant_id     uuid NOT NULL,\n  message_id    uuid NOT NULL,\n  system        integration_system NOT NULL,\n  direction     integration_direction NOT NULL,\n  entity_type   varchar(60) NOT NULL,\n  entity_id     uuid,\n  payload       jsonb NOT NULL,\n  status        integration_status NOT NULL DEFAULT 'PENDING',\n  attempts      smallint NOT NULL DEFAULT 0,\n  last_error    text,\n  next_attempt_at timestamptz NOT NULL DEFAULT now(),\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  processed_at  timestamptz,\n  PRIMARY KEY (tenant_id, message_id)\n);\nALTER TABLE integration_outbox ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_integration_outbox ON integration_outbox\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\nCREATE INDEX idx_integration_pending\n  ON integration_outbox (next_attempt_at)\n  WHERE status IN ('PENDING', 'FAILED') AND attempts < 8;\n\n-- Mapeo IDs externos (Procore project id <-> our project_id)\nCREATE TABLE external_id_map (\n  tenant_id       uuid NOT NULL,\n  system          integration_system NOT NULL,\n  external_type   varchar(60) NOT NULL,\n  external_id     varchar(120) NOT NULL,\n  internal_type   varchar(60) NOT NULL,\n  internal_id     uuid NOT NULL,\n  synced_at       timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, system, external_type, external_id)\n);\nALTER TABLE external_id_map ENABLE ROW LEVEL SECURITY;\nCREATE POLICY ti_external_id_map ON external_id_map\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);\n\n-- Seed plantillas mínimas (tenant-agnostic se inserta en runtime por seed service)